function splitArray(nums, k) {
  const n = nums.length;
  const prefix = [0];
  for (const x of nums) prefix.push(prefix[prefix.length - 1] + x);
  const best = Array.from({ length: k + 1 }, () => Array(n + 1).fill(Infinity));
  best[0][0] = 0;                                  // zero values in zero pieces
  for (let j = 1; j <= k; j++) {
    for (let i = 1; i <= n; i++) {
      for (let p = j - 1; p < i; p++) {            // the last piece is nums[p..i-1]
        best[j][i] = Math.min(best[j][i], Math.max(best[j - 1][p], prefix[i] - prefix[p]));
      }
    }
  }
  return best[k][n];
}

