int splitArray(int[] nums, int k) {
    long low = 0, high = 0;
    for (int x : nums) { low = Math.max(low, x); high += x; }   // biggest value .. total
    while (low < high) {
        long mid = low + (high - low) / 2;
        if (pieces(nums, mid) <= k) high = mid;   // possible: try a smaller limit
        else low = mid + 1;                       // needs more than k pieces: raise the limit
    }
    return (int) low;
}

